#!/usr/bin/env python3
# Some portions generated by Codex. Qualification only; diagnostic elapsed times are not performance evidence.
import pathlib,json,sys
r=pathlib.Path(sys.argv[1]);out={}
for kind in ('broad','scan','probes'):
 for regime in ('regular','interpreted','janino'):
  cell=kind+'-'+regime; arms={}
  for arm in ('A','B0','B1'):
   p=r/(cell+'-'+arm+'.log'); lines=p.read_text().splitlines();records={}
   for prefix in ('audit ','ownedDiagnostic '):
    vals=[dict(t.split('=',1) for t in l.split()[1:]) for l in lines if l.startswith(prefix)]
    records[prefix.strip()]=vals
   arms[arm]={'completed':len(records['audit'])==1,'records':records,
              'errors':[l for l in lines if 'Exception' in l or 'could not be forced' in l][:5]}
  ok=all(a['completed'] for a in arms.values());match=False;owned=False;off=False
  if ok:
   checks={tuple(a['records']['audit'][0][k] for k in ('rows','checksum','checksum2')) for a in arms.values()};match=len(checks)==1
   on=arms['B1']['records']['ownedDiagnostic'];offr=arms['B0']['records']['ownedDiagnostic']
   owned=bool(on and on[0]['supported']=='true' and int(on[0]['binds'])>0 and int(on[0]['polls'])>0)
   off=bool(offr and offr[0]['supported']=='true' and all(int(offr[0][k])==0 for k in ('binds','polls','resets')))
  out[cell]={'allArmsCompleted':ok,'checksumsMatch':match,'B0OwnedMetricsZero':off,'B1OwnedPhysicalPathHit':owned,
             'qualifiedForOwnedPathTiming':ok and match and off and owned,'arms':arms}
print(json.dumps({'scope':'untimed diagnostic; missing baseline metrics are unavailable not zero; no timing claims','cells':out},indent=2))
